import sys

def count_unique(array, start, end):
    seen = [False] * 24
    count = 0
    for i in range(start, end + 1):
        c = array[i]
        if not seen[c]:
            seen[c] = True
            count += 1
    return count

def main():
    input_line = sys.stdin.readline().strip()
    a, b, l, r = map(int, input_line.split())
    l -= 1
    r -= 1

    total_segments = a + b
    repeats = 4
    pattern_array = [0] * (total_segments * repeats)

    segment_shift = l // total_segments
    l -= segment_shift * total_segments
    r -= segment_shift * total_segments

    segment_count = (r - l + 1) // total_segments
    if segment_count > 2:
        r -= (segment_count - 2) * total_segments

    diff_val = a - b if a > b else 1

    for rep in range(repeats):
        for k in range(a - diff_val):
            pattern_array[(a + b) * rep + k] = k
        for k in range(diff_val):
            pattern_array[(a + b) * rep + a - diff_val + k] = (a - diff_val + k) if rep % 2 == 0 else a + k

    min_distinct = a + a
    for shiftA in range(1, diff_val + 1):
        for k in range(b):
            pattern_array[(a + b) * 0 + a + k] = pattern_array[(a + b) * 0 + a - shiftA]
        for shiftB in range(1, diff_val + 1):
            for k in range(b):
                pattern_array[(a + b) * 1 + a + k] = pattern_array[(a + b) * 1 + a - shiftB]
            for shiftC in range(1, diff_val + 1):
                for k in range(b):
                    pattern_array[(a + b) * 2 + a + k] = pattern_array[(a + b) * 2 + a - shiftC]
                for k in range(b):
                    pattern_array[(a + b) * 3 + a + k] = pattern_array[(a + b) * 3 + a - shiftC]
                min_distinct = min(min_distinct, count_unique(pattern_array, l, r))
    print(min_distinct)

if __name__ == "__main__":
    main()

